import java.nio.file.*;import java.sql.*;import java.util.*;
class CleanupTestProfiles{public static void main(String[]x)throws Exception{Properties p=new Properties();try(var r=Files.newBufferedReader(Path.of(".env"))){p.load(r);}Class.forName("org.mariadb.jdbc.Driver");try(var c=DriverManager.getConnection(System.getenv().getOrDefault("DB_URL",p.getProperty("DB_URL")),System.getenv().getOrDefault("DB_USERNAME",p.getProperty("DB_USERNAME")),System.getenv().getOrDefault("DB_PASSWORD",p.getProperty("DB_PASSWORD")))){try(var s=c.createStatement();var r=s.executeQuery("SELECT p.id,u.id FROM profile p JOIN `user` u ON u.id=p.user_id WHERE u.email LIKE 'tc-pr002-%@example.com'")){var ids=new ArrayList<long[]>();while(r.next())ids.add(new long[]{r.getLong(1),r.getLong(2)});for(var id:ids){try(var q=c.prepareStatement("DELETE FROM sport_preference WHERE profile_id=?")){q.setLong(1,id[0]);q.executeUpdate();}try(var q=c.prepareStatement("DELETE FROM profile WHERE id=?")){q.setLong(1,id[0]);q.executeUpdate();}try(var q=c.prepareStatement("DELETE FROM `user` WHERE id=?")){q.setLong(1,id[1]);q.executeUpdate();}System.out.println("cleaned user "+id[1]);}}}}}
